argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$target='e8033f2e42bd335c10a397eb3d2cb62c8bb837a9';
$branch='agent/bridge-r42-live-control-plane-cutover-20261006';
$temp=Join-Path $env:TEMP ('r42-cutover-' + $target + '.ps1');
& git.exe -C $repo fetch origin $branch;
if($LASTEXITCODE -ne 0){ throw "git fetch failed: $LASTEXITCODE" }
$psi=[Diagnostics.ProcessStartInfo]::new();
$psi.FileName='git.exe';
$psi.ArgumentList.Add('-C');$psi.ArgumentList.Add($repo);
$psi.ArgumentList.Add('show');$psi.ArgumentList.Add(($target + ':app/r42-cutover.ps1'));
$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;
$p=[Diagnostics.Process]::Start($psi);$src=$p.StandardOutput.ReadToEnd();$err=$p.StandardError.ReadToEnd();$p.WaitForExit();
if($p.ExitCode -ne 0 -or [string]::IsNullOrWhiteSpace($src)){ throw "git show cutover script failed: $err" }
[IO.File]::WriteAllText($temp,$src,[Text.UTF8Encoding]::new($false));
try{
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $temp -TargetSha $target -TargetBranch $branch -RepoPath $repo;
  if($LASTEXITCODE -ne 0){ throw "R42 cutover script failed with exit $LASTEXITCODE" }
} finally {
  Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
}
